package com.dudleylane.quickfix.fix41;

/** FIX 4.1 Heartbeat (35=0). Generated by spec/GeneratorJava.rb. */
public class Heartbeat extends Message {
    public static final String MSGTYPE = "0";

    public Heartbeat() {
        getHeader().setField(35, MSGTYPE);
    }

    private Heartbeat(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a Heartbeat, without copying it: the same engine object, so valid only while message is. A
     * callback's message is the engine's and lasts only for the callback; copy it (new Message(message)) to keep it.
     */
    public static Heartbeat view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a Heartbeat (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        return new Heartbeat(getCPtr(message));
    }
}
